import unittest
from solution import occurrence_count

class T(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(occurrence_count("a b a"), {"a": 2, "b": 1})
    def test_case(self):
        self.assertEqual(occurrence_count("Hi hi HI"), {"hi": 3})
    def test_empty(self):
        self.assertEqual(occurrence_count(""), {})
    def test_whitespace(self):
        self.assertEqual(occurrence_count("a  b\ta\nb"), {"a": 2, "b": 2})
    def test_single(self):
        self.assertEqual(occurrence_count("solo"), {"solo": 1})
